import { Controller, HttpCode, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 설정 영역·키는 BEHAVIOR.md 값의 출처의 고정값이다.
const SETTING_AREA = 'APPROVAL';
const SETTING_KEY = 'HWP_WEB_DRAFTER_LICENSE';

@Controller('api/v1')
export class FnSfr03003Controller {
  @Put('/config-settings/hwp-web-drafter-license')
  async applyHwpWebDrafterLicense(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const settingValue = data['settingValue'];
    if (typeof settingValue !== 'string' || settingValue.trim() === '' || settingValue.length > 1000) {
      throw new ApiError(400, 'VALIDATION_FAILED', '라이선스 값을 1000자 이내로 입력해 주세요.');
    }
    // TODO(질문): 라이선스 값이 유효한지 판단하는 기준이 입력에 없어 422 LICENSE_INVALID 검사는 구현하지 못했다.
    return transaction(async (db) => {
      // 가정: 적용 시작일은 현재 날짜이고, 같은 날 다시 적용하면 값을 덮어쓴다.
      const rows = await db.query(
        `INSERT INTO config_setting (setting_area, setting_key, setting_value, applied_from, created_at, updated_at)
         VALUES (:settingArea, :settingKey, :settingValue, CAST(now() AS date), now(), now())
         ON CONFLICT (setting_area, setting_key, applied_from)
         DO UPDATE SET setting_value = :settingValue, updated_at = now()
         RETURNING config_setting_id AS "configSettingId", setting_value AS "settingValue"`,
        { settingArea: SETTING_AREA, settingKey: SETTING_KEY, settingValue: settingValue },
      );
      return rows[0];
    });
  }
}

