import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  NumberInput,
  Pager,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Column, PageProps, Page, Row } from '../kit';

export default function FnSfr03003Page({ role, notify }: PageProps) {
  const [useStatus, setUseStatus] = useState('사용');
  const [pageNo, setPageNo] = useState(0);
  const [drawer, setDrawer] = useState<'license' | 'draft' | 'submit' | ''>('');
  const [licenseValue, setLicenseValue] = useState('');
  const [form, setForm] = useState<Row | null>(null);
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [linkedType, setLinkedType] = useState('');
  const [linkedId, setLinkedId] = useState<number | string>('');
  const [target, setTarget] = useState<Row | null>(null);
  const [approverId, setApproverId] = useState<number | string>('');
  const [drafts, setDrafts] = useState<Row[]>([]);

  const forms = useData<Page>(
    () => call<Page>('GET', '/approval-forms', role, undefined, { useStatus, page: pageNo, size: 20 }),
    [useStatus, pageNo],
  );

  const closeDrawer = () => setDrawer('');

  const applyLicense = async () => {
    if (licenseValue.trim() === '') {
      throw new Error('라이선스 값을 입력해 주세요.');
    }
    await call('PUT', '/config-settings/hwp-web-drafter-license', role, { settingValue: licenseValue });
    notify('한글웹기안기 라이선스를 적용했습니다.');
    setLicenseValue('');
    closeDrawer();
  };

  const openDraft = (row: Row) => {
    setForm(row);
    setTitle('');
    setBody('');
    setLinkedType('');
    setLinkedId('');
    setDrawer('draft');
  };

  const createDraft = async () => {
    if (!form || title.trim() === '' || linkedType.trim() === '' || linkedId === '') {
      throw new Error('문서 제목, 연계 업무 유형, 연계 업무 식별자를 입력해 주세요.');
    }
    const created = await call('POST', '/approval-documents', role, {
      approvalFormId: form['approvalFormId'],
      title,
      body,
      linkedBusinessType: linkedType,
      linkedBusinessId: linkedId,
    });
    setDrafts([{ ...created, title }, ...drafts]);
    notify('한글 웹기안 문서를 작성했습니다.');
    closeDrawer();
  };

  const openSubmit = (row: Row) => {
    setTarget(row);
    setApproverId('');
    setDrawer('submit');
  };

  const submitDraft = async () => {
    if (!target || approverId === '') {
      throw new Error('결재자를 선택해 주세요.');
    }
    // 가정: 결재선 항목은 결재자·결재선 구분·결재 순서로 구성한다.
    const result = await call('POST', `/approval-documents/${target['approvalDocumentId']}/submit`, role, {
      approvalLines: [{ approverId, lineGroup: 1, sequenceNo: 1 }],
    });
    setDrafts(drafts.map((d) => (d['approvalDocumentId'] === target['approvalDocumentId'] ? { ...d, ...result } : d)));
    notify('전자결재로 상신했습니다.');
    closeDrawer();
  };

  const formColumns: Column[] = [
    { key: 'formName', label: '결재양식명' },
    { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r['useStatus']} /> },
    {
      key: 'action',
      label: '처리',
      render: (r) =>
        r['useStatus'] === '사용' ? (
          <button type="button" onClick={() => openDraft(r)}>
            기안 작성
          </button>
        ) : null,
    },
  ];

  const draftColumns: Column[] = [
    { key: 'documentNumber', label: '문서번호' },
    { key: 'title', label: '문서 제목' },
    { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
    { key: 'submittedAt', label: '상신 일시', render: (r) => <DateText value={r['submittedAt']} time /> },
    {
      key: 'action',
      label: '처리',
      render: (r) =>
        r['approvalStatus'] === '기안' ? (
          <button type="button" onClick={() => openSubmit(r)}>
            상신
          </button>
        ) : null,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>결재 양식</h2>
        <Filters
          onSearch={() => setPageNo(0)}
          onReset={() => {
            setUseStatus('사용');
            setPageNo(0);
          }}
        >
          <Field label="사용 여부">
            <Select
              value={useStatus}
              onChange={(v) => {
                setUseStatus(v);
                setPageNo(0);
              }}
              options={[
                ['사용', '사용'],
                ['미사용', '미사용'],
              ]}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={forms.data?.total}>
          <button type="button" onClick={() => setDrawer('license')}>
            라이선스 적용
          </button>
        </Band>
        {forms.error ? <p>{forms.error}</p> : null}
        <DataTable columns={formColumns} rows={forms.data?.items ?? []} empty="결재 양식이 없습니다." />
        <Pager page={pageNo} size={20} total={forms.data?.total ?? 0} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>작성한 웹기안</h2>
        <DataTable columns={draftColumns} rows={drafts} empty="작성한 문서가 없습니다." />
      </section>
      {drawer === 'license' ? (
        <Drawer title="한글웹기안기 라이선스 적용" onClose={closeDrawer}>
          <Form onSubmit={applyLicense} submit="적용">
            <Field label="라이선스 값" required wide>
              <TextInput value={licenseValue} onChange={setLicenseValue} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {drawer === 'draft' && form ? (
        <Drawer title={`한글 웹기안 작성 - ${String(form['formName'])}`} onClose={closeDrawer}>
          <Form onSubmit={createDraft} submit="작성">
            <Field label="문서 제목" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="연계 업무 유형" required>
              <TextInput value={linkedType} onChange={setLinkedType} />
            </Field>
            <Field label="연계 업무 식별자" required>
              <NumberInput value={linkedId} onChange={setLinkedId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {drawer === 'submit' && target ? (
        <Drawer title="전자결재 상신" onClose={closeDrawer}>
          <Form onSubmit={submitDraft} submit="상신">
            <Field label="결재자" required wide>
              <LookupSelect table="employee" role={role} value={approverId} onChange={setApproverId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
